import React from 'react';

import { NavLink } from 'react-router-dom';

import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import { IEquipSetListItem } from '@apps/Hiking/@types/equip.types';
import PohAva from '@ui-kit/Ava';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IEquipSetListItemProps {
  item: IEquipSetListItem;
}

const EquipSetListItem: React.FC<IEquipSetListItemProps> = ({ item }) => {
  return (
    <PohRow>
      <PohCol sm={2} className="text-end" style={{ lineHeight: 0.8 }}>
        {item.backpack && (
          <div className="d-flex align-items-center justify-content-md-end justify-content-around">
            <small className="flex-grow-0">
              {item.backpack.name}
              <small className="d-block text-muted mt-1">
                {item.backpack.value}l. {item.backpack.weight}kg.
              </small>
            </small>
            <PohAva
              title={item.backpack.name}
              alt={item.backpack.name}
              colorize
              src={item.backpack.photo}
              className="ml-1 flex-shrink-0"
              width={42}
            />
          </div>
        )}
      </PohCol>
      <PohCol sm={6}>
        <strong>{item.name}</strong>
        <small className="text-muted d-block">
          <small className="d-inline-block mr-2">
            {item.date_update.toLocaleDateString()} &nbsp;
          </small>
          {item.name !== item.description && <em>{item.description}</em>}
        </small>
      </PohCol>
      {item.hiking && (
        <PohCol sm={4} onClick={(e) => e.stopPropagation()}>
          <NavLink to={`/hiking/${item.hiking?.id}`} className="text-body">
            <HikingBadge hiking={item.hiking} />
          </NavLink>
        </PohCol>
      )}
    </PohRow>
  );
};

export default EquipSetListItem;
